            result.Add(new PerClassMetrics
            {
                Class = i < _classLabels.Length ? _classLabels[i] : $"Class_{i}",
                Precision = precision,
                Recall = recall,
                F1Score = f1
            });
        }
        return result.ToArray();
    }

