private PerClassMetrics[] BuildPerClassMetrics(MulticlassClassificationMetrics metrics)
{
    var result = new List<PerClassMetrics>();
    for (int i = 0; i < metrics.PerClassPrecision.Count; i++)
    {
        double precision = metrics.PerClassPrecision[i];
        double recall = metrics.PerClassRecall[i];
        double f1 = (precision + recall) > 0
            ? 2 * precision * recall / (precision + recall)
            : 0;

        result.Add(new PerClassMetrics
        {
            Class = i < _classLabels.Length ? _classLabels[i] : $"Class_{i}",
            Precision = precision,
            Recall = recall,
            F1Score = f1
        });
    }
    return result.ToArray();
}

